style.css:
@-moz-document domain("roblox.com") {
/* --- Core Theme: Cute Baby Blue & White Accent --- */
    :root {
        --baby-blue-bg: #E3F2FD;       
        --baby-blue-card: #FFFFFF;     
        --baby-blue-accent: #90CAF9;   
        --baby-blue-text: #42A5F5;     
        --baby-blue-subtext: #64B5F6;  
        --kawaii-radius: 20px;         
    }

    /* Apply the cute font and baby blue text color globally */
    body, 
    .dark-mode, 
    .light-mode,
    .wrap-container,
    #container-main,
    .content,
    h1, h2, h3, h4, h5, h6, a, p, span, div {
        font-family: 'Quicksand', 'Nunito', 'Segoe UI', sans-serif !important;
        color: var(--baby-blue-text) !important;
    }

    /* --- [NEW] Make All Icons Baby Blue --- */
    /* Targets Roblox SVG Icons, Font Icons, and Navigation Icons */
    .icon-default,
    .icon-nav,
    .icon-robux-28g,
    .icon-robux-16g,
    .icon-logo,
    .icon-logo-r,
    [class^="icon-"], 
    [class*=" icon-"],
    .svg-icon,
    span[class*="icon"] {
        /* Changes the color of SVG/Vector icons */
        fill: var(--baby-blue-text) !important; 
        /* Changes the color of font-based icons */
        color: var(--baby-blue-text) !important; 
        /* Forces standard colors to blend into baby blue */
        filter: drop-shadow(0px 0px 0px var(--baby-blue-text)) !important;
    }

    /* Special adjustment for images used as icons/logos to tint them blue */
    img[src*="icon"], img[src*="logo"] {
        filter: sepia(100%) hue-rotate(190deg) saturate(300%) brightness(95%) !important;
    }

    /* Change main website background */
    body, 
    .dark-mode, 
    .light-mode,
    .wrap-container,
    #container-main,
    .content {
        background-color: var(--baby-blue-bg) !important;
        background-image: none !important;
    }

    /* Minimalist Top Navigation Header */
    #header {
        background-color: rgba(255, 255, 255, 0.85) !important;
        backdrop-filter: blur(10px);
        border-bottom: 3px solid #FFFFFF !important; 
    }

    /* White Corners and Cards with Baby Blue Borders */
    .section-content,
    .game-card-container,
    .item-card-container,
    .vngle-item-card,
    .friends-content,
    .create-avatar-item,
    .places-list-item,
    .feed-container,
    .chat-container,
    .modal-content,
    .roblox-popover-content,
    .dropdown-menu {
        background-color: var(--baby-blue-card) !important;
        border-radius: var(--kawaii-radius) !important;
        border: 4px solid #FFFFFF !important; 
        box-shadow: 0 4px 12px rgba(144, 202, 249, 0.25) !important;
        transition: transform 0.2s ease, box-shadow 0.2s ease;
    }

    /* Subtext/Muted text color adjustment */
    .text-muted, .text-description, .text-label, .game-card-developer {
        color: var(--baby-blue-subtext) !important;
    }

    /* Smooth Hover Effect for Game and Item Cards */
    .game-card-container:hover,
    .item-card-container:hover {
        transform: translateY(-5px) scale(1.02);
        box-shadow: 0 8px 20px rgba(144, 202, 249, 0.4) !important;
        border-color: #FFFFFF !important;
    }

    /* Custom Cute Buttons with White Borders */
    .btn-primary-md, 
    .btn-secondary-xs, 
    .btn-control-md,
    .btn-common-play-game {
        background-color: var(--baby-blue-accent) !important;
        border: 2px solid #FFFFFF !important;
        color: white !important;
        border-radius: 25px !important;
        font-weight: bold !important;
    }

    .btn-primary-md:hover,
    .btn-common-play-game:hover {
        background-color: #64B5F6 !important;
        filter: brightness(1.05);
    }

    /* Left Sidebar Navigation */
    #navigation {
        background-color: rgba(255, 255, 255, 0.9) !important;
    }

    .left-col-list li a {
        border-radius: var(--kawaii-radius) !important;
        margin: 4px 8px !important;
    }

    .left-col-list li a:hover {
        background-color: var(--baby-blue-bg) !important;
        color: var(--baby-blue-text) !important;
    }

    /* Hide ads for a cleaner, ultra-minimal look */
    .abp, 
    .AdContainer, 
    #AdvertisingLeaderboard, 
    .ad-annotations {
        display: none !important;
    }
}
